WITH valid_web_events AS (SELECT * FROM web_events WHERE event_type NOT IN ('purchase', 'add_to_cart', 'click')), summary AS (SELECT DATE_FORMAT(event_time, 'yyyy-MM') event_month, ROUND(AVG(duration_sec), 2) avg_duration_sec, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(page))) page_values FROM valid_web_events GROUP BY DATE_FORMAT(event_time, 'yyyy-MM')) SELECT event_month, avg_duration_sec FROM summary WHERE avg_duration_sec > 43 ORDER BY 1 DESC, avg_duration_sec DESC LIMIT 10
